message.content:
[
 {
  "n": "G1",
  "m": true,
  "mc": "Technical notes confirm the page loaded and rendered in Chromium with no console or page errors."
 },
 {
  "n": "G2",
  "m": null,
  "mc": "Technical notes state that frame rate was only observed under software rendering and was not measured on a standard laptop GPU; a hardware-accelerated FPS test is needed."
 },
 {
  "n": "G3",
  "m": true,
  "mc": "Technical notes confirm playback starts on load, pause freezes the scene on the current frame, and play resumes from that exact frame."
 },
 {
  "n": "1",
  "m": true,
  "mc": "Technical notes confirm WebGL renders 3D depth-recovered meshes from moving camera positions, synthesizing five out of every six frames live rather than playing a video or flat frame sequence."
 },
 {
  "n": "2",
  "m": true,
  "mc": "No text, logos, overlays, or extra objects appear in the scene across the entire capture."
 },
 {
  "n": "3",
  "m": true,
  "mc": "Dense broadleaf forest covers the near hills and fills the lower half of the frame at 0:00 and in Still 1."
 },
 {
  "n": "4",
  "m": true,
  "mc": "Layered background ridges span the full width with the exact skyline profile of the reference throughout the clip."
 },
 {
  "n": "5",
  "m": true,
  "mc": "The brown tilled clearing emerges among the trees and dominates the lower-middle view from 0:10 onward."
 },
 {
  "n": "6",
  "m": true,
  "mc": "The greenhouse complex with white/silver tunnel roofs and the red-roofed building sits at the lower right from 0:15 to 0:19."
 },
 {
  "n": "7",
  "m": true,
  "mc": "The pale dirt track and small dark pond are clearly visible at the lower right around 0:04–0:06 and in Still 2."
 },
 {
  "n": "8",
  "m": true,
  "mc": "Terraced striped crop plots and small green-roofed buildings populate the right valley across all stills."
 },
 {
  "n": "9",
  "m": true,
  "mc": "The cloudless sky grades smoothly from bright pale haze at the upper left to teal blue on the right."
 },
 {
  "n": "10",
  "m": true,
  "mc": "Daytime sunlight, warm foreground greens, and cooler distant blue-greens match the video across all frames."
 },
 {
  "n": "11",
  "m": true,
  "mc": "The scene immediately reads as an aerial flyover of forested hills and valley farmland."
 },
 {
  "n": "12",
  "m": true,
  "mc": "The hills display rounded slopes, valleys, and 3D parallax during the flyover rather than acting as a flat plane."
 },
 {
  "n": "13",
  "m": true,
  "mc": "The canopy resolves into varied individual tree crowns throughout the foreground and middle ground."
 },
 {
  "n": "14",
  "m": false,
  "mc": "In Close-ups 1 and 2, several greenhouse roof lines slightly bend and smear where foreground tree depth meshes overlap them."
 },
 {
  "n": "15",
  "m": true,
  "mc": "Still 1 matches the video's opening composition with the horizon a third down, ridges mid-frame, and forest below."
 },
 {
  "n": "16",
  "m": true,
  "mc": "The horizon remains level from start to finish."
 },
 {
  "n": "17",
  "m": true,
  "mc": "Directional light from the upper left matches the video's bright sky gradient and sunlit tree crowns."
 },
 {
  "n": "18",
  "m": true,
  "mc": "Distant mountain ridges appear paler and bluer than the near hills, matching the video's atmospheric haze."
 },
 {
  "n": "19",
  "m": true,
  "mc": "Exposure stays balanced with preserved shadow detail in the trees and no unnatural clipping."
 },
 {
  "n": "20",
  "m": true,
  "mc": "Cast tree shadows along the near edge of the tilled field and dirt track match the reference in Stills 3 and 4."
 },
 {
  "n": "21",
  "m": true,
  "mc": "Tree crowns show matte, mottled light and dark green leaf detail rather than flat or plastic shading."
 },
 {
  "n": "22",
  "m": true,
  "mc": "Close-up 3 and Still 4 show clear plough lines and bare soil texture across the tilled field."
 },
 {
  "n": "23",
  "m": true,
  "mc": "Close-ups 1 and 2 show bright reflective greenhouse sheeting alongside a distinct matte red roof."
 },
 {
  "n": "24",
  "m": true,
  "mc": "Scene elements remain static relative to the ground with no invented foliage, water, or cloud animation."
 },
 {
  "n": "25",
  "m": true,
  "mc": "Technical notes confirm that after frame 464 the playback cuts cleanly back to the first frame."
 },
 {
  "n": "26",
  "m": true,
  "mc": "Projected photographic imagery shows natural variation with no repeating tiles or cloned tree meshes."
 },
 {
  "n": "27",
  "m": false,
  "mc": "Stretched and smeared surfaces appear along depth discontinuities where tree outlines cross the greenhouses, tilled soil, and pond in Close-ups 1, 3, and 4."
 },
 {
  "n": "28",
  "m": true,
  "mc": "Side-by-side stills show that a paused frame easily passes for a video frame at first glance."
 },
 {
  "n": "29",
  "m": true,
  "mc": "The camera flies straight forward at a steady altitude and angle without unwanted turning or rolling."
 },
 {
  "n": "30",
  "m": true,
  "mc": "Technical notes and the capture show a smooth 19.3-second advance with even speed."
 },
 {
  "n": "31",
  "m": true,
  "mc": "Still 6 matches the final video frame with the greenhouses lower right, tilled field bottom left, and unchanged background ridges."
 },
 {
  "n": "32",
  "m": false,
  "mc": "Between the 6-frame mesh updates, newly revealed ground behind foreground tree lines exhibits stretched rubber-sheet fill at occlusion edges."
 },
 {
  "n": "33",
  "m": false,
  "mc": "Stepping between the 78 discrete depth meshes every six frames produces subtle periodic popping and edge shifting along near treetops in the capture."
 },
 {
  "n": "34",
  "m": true,
  "mc": "The rendered image fills the frame cleanly to all borders throughout the clip."
 },
 {
  "n": "35",
  "m": true,
  "mc": "Parallax matches the video, with near treetops sweeping past rapidly while mid-hills move slowly and far ridges stay nearly fixed."
 },
 {
  "n": "36",
  "m": true,
  "mc": "The pond at 0:05, tilled field at 0:10, red roof at 0:14, and full greenhouse complex at 0:18–0:19 all appear on schedule."
 },
 {
  "n": "37",
  "m": true,
  "mc": "All six comparison stills show scene features aligned in the exact same screen positions as the reference video."
 }
]
